mapper.select:
select focus_user_id as user_id,count(1) statistics_count from user_focus where
 DATE_FORMAT(focus_time,'%Y-%m-%d')=#{statisticsDate}
group by focus_user_id

select video_user_id as user_id,count(1) statistics_count from video_comment where
 DATE_FORMAT(post_time,'%Y-%m-%d')=#{statisticsDate}
group by video_user_id

select user_id as user_id,count(1) statistics_count from video_danmu where
 DATE_FORMAT(post_time,'%Y-%m-%d')=#{statisticsDate}
group by user_id

select video_user_id as user_id,action_type data_type,sum(action_count) statistics_count
from user_action where  DATE_FORMAT(action_time,'%Y-%m-%d')=#{statisticsDate}
and action_type in

    #{item}

group by video_user_id,action_type

SELECT

FROM statistics_info


        AND user_id = #{query.userId}


        AND statistics_date = #{query.statisticsDate}


        AND data_type = #{query.dataType}


         AND statistics_date >= #{query.statisticsDateStart} 


         AND statistics_date <= #{query.statisticsDateEnd} 



    ORDER BY ${query.orderBy}

SELECT data_type, ifnull(sum(statistics_count),0) statistics_count
FROM statistics_info


        AND user_id = #{query.userId}


        AND statistics_date = #{query.statisticsDate}


        AND data_type = #{query.dataType}


         AND statistics_date >= #{query.statisticsDateStart} 


         AND statistics_date <= #{query.statisticsDateEnd} 


GROUP BY data_type
